import React, { useState, useEffect, useCallback } from 'react';
import { 
  Users, 
  Receipt, 
  Bus, 
  Search, 
  Trash2, 
  User as UserIcon, 
  Phone, 
  Mail, 
  ShieldCheck, 
  Info, 
  Eye, 
  CheckCircle2,
  Lock,
  Calendar,
  Ticket,
  MapPin,
  Clock,
  TrendingUp,
  X
} from 'lucide-react';

export default function Admin({ activeTab = 'Dashboard' }) {
  const [registeredUsers, setRegisteredUsers] = useState([]);
  const [allTickets, setAllTickets] = useState([]);
  const [allBuses, setAllBuses] = useState([]);
  
  // Search & Filter
  const [searchTerm, setSearchTerm] = useState('');
  
  // Selected User for Full History Modal
  const [selectedUserHistory, setSelectedUserHistory] = useState(null);

  // Load Data
  const loadAdminData = useCallback(() => {
    // 1. Registered Users
    const users = JSON.parse(localStorage.getItem('app_users') || '[]');
    setRegisteredUsers(users);

    // 2. All Ticket Purchases
    const tickets = JSON.parse(localStorage.getItem('app_tickets') || '[]');
    setAllTickets(tickets);

    // 3. All Buses
    const buses = JSON.parse(localStorage.getItem('app_buses') || '[]');
    setAllBuses(buses);
  }, []);

  useEffect(() => {
    loadAdminData();
    const handleStorage = () => loadAdminData();
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, [loadAdminData]);

  // Delete User
  const handleDeleteUser = (userEmail) => {
    if (window.confirm(`Are you sure you want to remove user: ${userEmail}?`)) {
      const updatedUsers = registeredUsers.filter((u) => u.email !== userEmail);
      localStorage.setItem('app_users', JSON.stringify(updatedUsers));
      setRegisteredUsers(updatedUsers);
      if (selectedUserHistory?.email === userEmail) {
        setSelectedUserHistory(null);
      }
    }
  };

  // Filter Registered Users
  const filteredUsers = registeredUsers.filter((u) => {
    const query = searchTerm.toLowerCase();
    const nameMatch = u.name?.toLowerCase().includes(query);
    const emailMatch = u.email?.toLowerCase().includes(query);
    const phoneMatch = u.phone?.includes(query);
    return nameMatch || emailMatch || phoneMatch;
  });

  // Calculate User Specific History Data
  const getUserPaymentHistory = (user) => {
    return allTickets.filter((ticket) => {
      const matchEmail = ticket.userEmail && ticket.userEmail.toLowerCase() === user.email?.toLowerCase();
      const matchPhone = ticket.passengerPhone && ticket.passengerPhone === user.phone;
      return matchEmail || matchPhone;
    });
  };

  const totalRevenue = allTickets.reduce((sum, t) => sum + (Number(t.fare) || 0), 0);

  const tab = (activeTab || 'dashboard').toLowerCase();

  return (
    <div style={styles.container}>

      {/* DASHBOARD SUMMARY TAB */}
      {(tab === 'dashboard') && (
        <div style={styles.dashboardGrid}>
          <div style={styles.statCard}>
            <div style={{ ...styles.statIcon, backgroundColor: '#38bdf8' }}>
              <Users size={24} color="#18181b" />
            </div>
            <div>
              <span style={styles.statLabel}>Registered Passengers</span>
              <h3 style={styles.statValue}>{registeredUsers.length}</h3>
            </div>
          </div>

          <div style={styles.statCard}>
            <div style={{ ...styles.statIcon, backgroundColor: '#22c55e' }}>
              <Receipt size={24} color="#18181b" />
            </div>
            <div>
              <span style={styles.statLabel}>Total Tickets Sold</span>
              <h3 style={styles.statValue}>{allTickets.length}</h3>
            </div>
          </div>

          <div style={styles.statCard}>
            <div style={{ ...styles.statIcon, backgroundColor: '#ea580c' }}>
              <TrendingUp size={24} color="#18181b" />
            </div>
            <div>
              <span style={styles.statLabel}>Total Sales Revenue</span>
              <h3 style={styles.statValue}>৳ {totalRevenue}</h3>
            </div>
          </div>

          <div style={styles.statCard}>
            <div style={{ ...styles.statIcon, backgroundColor: '#eab308' }}>
              <Bus size={24} color="#18181b" />
            </div>
            <div>
              <span style={styles.statLabel}>Active Bus Fleets</span>
              <h3 style={styles.statValue}>{allBuses.length}</h3>
            </div>
          </div>
        </div>
      )}

      {/* REGISTERED USERS MANAGEMENT TAB */}
      {(tab === 'users' || tab === 'registered users' || tab === 'dashboard') && (
        <div style={styles.contentSection}>
          <div style={styles.sectionHeader}>
            <div>
              <h3 style={styles.sectionTitle}>Registered Passengers Directory</h3>
              <p style={{ margin: '4px 0 0 0', color: '#a1a1aa', fontSize: '0.85rem' }}>
                View complete passenger details, photos, and personal purchase history.
              </p>
            </div>

            <div style={styles.searchBox}>
              <Search size={16} color="#71717a" />
              <input 
                type="text" 
                placeholder="Search by name, email, or phone..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={styles.searchInput}
              />
            </div>
          </div>

          {filteredUsers.length === 0 ? (
            <div style={styles.emptyCard}>
              <Users size={48} color="#71717a" />
              <p style={{ color: '#a1a1aa', margin: '12px 0 0 0' }}>No registered users found.</p>
            </div>
          ) : (
            <div style={styles.tableWrapper}>
              <table style={styles.table}>
                <thead>
                  <tr style={styles.tableHeaderRow}>
                    <th style={styles.th}>SL ID</th>
                    <th style={styles.th}>Profile Photo</th>
                    <th style={styles.th}>Full Name</th>
                    <th style={styles.th}>Phone Number</th>
                    <th style={styles.th}>Email Address</th>
                    <th style={styles.th}>Tickets Purchased</th>
                    <th style={{ ...styles.th, textAlign: 'center' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredUsers.map((u, index) => {
                    const userTickets = getUserPaymentHistory(u);
                    // SERIAL NUMBER ID: 1, 2, 3, etc.
                    const serialId = index + 1;

                    return (
                      <tr key={u.email || index} style={styles.tableRow}>
                        {/* SERIAL NO */}
                        <td style={styles.td}>
                          <span style={styles.serialBadge}>#{serialId}</span>
                        </td>

                        {/* PHOTO */}
                        <td style={styles.td}>
                          {u.avatar ? (
                            <img src={u.avatar} alt={u.name} style={styles.userTableAvatar} />
                          ) : (
                            <div style={styles.userTableAvatarFallback}>
                              <UserIcon size={18} color="#ea580c" />
                            </div>
                          )}
                        </td>

                        {/* NAME */}
                        <td style={{ ...styles.td, fontWeight: '700', color: '#f4f4f5' }}>
                          {u.name || 'Passenger User'}
                        </td>

                        {/* PHONE */}
                        <td style={styles.td}>
                          <span style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#d4d4d8' }}>
                            <Phone size={12} color="#ea580c" /> {u.phone || 'N/A'}
                          </span>
                        </td>

                        {/* EMAIL */}
                        <td style={styles.td}>
                          <span style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#a1a1aa' }}>
                            <Mail size={12} color="#38bdf8" /> {u.email}
                          </span>
                        </td>

                        {/* TICKET COUNT */}
                        <td style={styles.td}>
                          <span style={styles.ticketCountTag}>
                            <Ticket size={12} /> {userTickets.length} Purchased
                          </span>
                        </td>

                        {/* ACTIONS */}
                        <td style={{ ...styles.td, textAlign: 'center' }}>
                          <div style={{ display: 'flex', gap: '8px', justifyContent: 'center' }}>
                            <button 
                              style={styles.viewHistoryBtn}
                              onClick={() => setSelectedUserHistory(u)}
                              title="View Full User Profile & Payment History"
                            >
                              <Eye size={14} /> Full History
                            </button>

                            <button 
                              style={styles.deleteBtn}
                              onClick={() => handleDeleteUser(u.email)}
                              title="Delete User"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* PERFECT ABOUT & SYSTEM INFO TAB FOR ADMIN */}
      {(tab === 'about') && (
        <div style={styles.contentSection}>
          <div style={styles.aboutBanner}>
            <div style={styles.aboutBadge}>
              <ShieldCheck size={16} color="#ea580c" /> Admin Console Controls
            </div>
            <h2 style={{ margin: '8px 0', color: '#f4f4f5' }}>Online Bus Ticket Reservation Portal</h2>
            <p style={{ color: '#a1a1aa', fontSize: '0.9rem', maxWidth: '700px', margin: '0 auto' }}>
              Centralized administrative hub for managing bus schedules, district routes, passenger profiles, and payment histories across Bangladesh.
            </p>
          </div>

          <div style={styles.aboutGrid}>
            <div style={styles.infoBox}>
              <Users size={24} color="#ea580c" />
              <h4 style={styles.infoTitle}>Sequential User Indexing</h4>
              <p style={styles.infoDesc}>Registered users are automatically cataloged with serial IDs (1, 2, 3...) for easy tracking and reference.</p>
            </div>

            <div style={styles.infoBox}>
              <Receipt size={24} color="#22c55e" />
              <h4 style={styles.infoTitle}>Audit-Ready Payment Logs</h4>
              <p style={styles.infoDesc}>Every payment and transaction ID (bKash, Nagad, Card) is tied directly to passenger user profiles.</p>
            </div>

            <div style={styles.infoBox}>
              <Lock size={24} color="#38bdf8" />
              <h4 style={styles.infoTitle}>Secure Profile Storage</h4>
              <p style={styles.infoDesc}>User avatars, contact information, and passcodes are synchronized across the system in real time.</p>
            </div>
          </div>
        </div>
      )}

      {/* FULL USER HISTORY MODAL */}
      {selectedUserHistory && (
        <div style={styles.modalOverlay} onClick={() => setSelectedUserHistory(null)}>
          <div style={styles.historyModal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                {selectedUserHistory.avatar ? (
                  <img src={selectedUserHistory.avatar} alt="User" style={styles.modalAvatarImg} />
                ) : (
                  <div style={styles.modalAvatarFallback}>
                    <UserIcon size={28} color="#ea580c" />
                  </div>
                )}
                <div>
                  <h3 style={{ margin: 0, color: '#f4f4f5', fontSize: '1.2rem' }}>
                    {selectedUserHistory.name || 'Passenger User'}
                  </h3>
                  <span style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>
                    Full Activity & Payment Audit Trail
                  </span>
                </div>
              </div>

              <button style={styles.closeBtn} onClick={() => setSelectedUserHistory(null)}>
                <X size={20} />
              </button>
            </div>

            {/* USER PROFILE INFO SUMMARY */}
            <div style={styles.userProfileSummaryBox}>
              <div style={styles.summaryItem}>
                <Phone size={14} color="#ea580c" />
                <span>Phone: <strong>{selectedUserHistory.phone || 'N/A'}</strong></span>
              </div>
              <div style={styles.summaryItem}>
                <Mail size={14} color="#38bdf8" />
                <span>Email: <strong>{selectedUserHistory.email}</strong></span>
              </div>
              <div style={styles.summaryItem}>
                <Receipt size={14} color="#22c55e" />
                <span>Total Spent: <strong>৳ {getUserPaymentHistory(selectedUserHistory).reduce((a, b) => a + (Number(b.fare) || 0), 0)}</strong></span>
              </div>
            </div>

            {/* PAYMENT & BOOKING HISTORY */}
            <div style={{ marginTop: '16px' }}>
              <h4 style={{ margin: '0 0 12px 0', color: '#ea580c', fontSize: '1rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <Receipt size={16} /> Payment & Ticket Purchases ({getUserPaymentHistory(selectedUserHistory).length})
              </h4>

              {getUserPaymentHistory(selectedUserHistory).length === 0 ? (
                <div style={styles.noHistoryBox}>
                  <p style={{ margin: 0, color: '#a1a1aa', fontSize: '0.85rem' }}>This passenger has not purchased any bus tickets yet.</p>
                </div>
              ) : (
                <div style={styles.historyCardsList}>
                  {getUserPaymentHistory(selectedUserHistory).map((ticket, i) => (
                    <div key={ticket.id || i} style={styles.historyCardItem}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <div>
                          <span style={styles.ticketIdBadge}>{ticket.id}</span>
                          <h4 style={{ margin: '4px 0 0 0', color: '#f4f4f5', fontSize: '1rem' }}>{ticket.busName}</h4>
                          <span style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>
                            Route: {ticket.route}
                          </span>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                          <span style={{ fontSize: '1.1rem', fontWeight: '800', color: '#22c55e', display: 'block' }}>
                            ৳ {ticket.fare}
                          </span>
                          <span style={styles.paymentMethodTag}>Paid via {ticket.paymentMethod || 'bKash'}</span>
                        </div>
                      </div>

                      <div style={styles.ticketFooterDetails}>
                        <span style={styles.detailChip}><Ticket size={12} color="#ea580c" /> Seat: {ticket.seatNumber}</span>
                        <span style={styles.detailChip}><Calendar size={12} color="#38bdf8" /> Date: {ticket.purchaseDate}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

          </div>
        </div>
      )}

    </div>
  );
}

const styles = {
  container: { display: 'flex', flexDirection: 'column', gap: '24px', color: '#ffffff' },
  
  dashboardGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '16px' },
  statCard: { backgroundColor: '#18181b', border: '1px solid #3f3f46', padding: '18px', borderRadius: '14px', display: 'flex', alignItems: 'center', gap: '16px' },
  statIcon: { width: '48px', height: '48px', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  statLabel: { fontSize: '0.8rem', color: '#a1a1aa', display: 'block' },
  statValue: { margin: '2px 0 0 0', fontSize: '1.4rem', fontWeight: '800', color: '#f4f4f5' },

  contentSection: { backgroundColor: '#18181b', border: '1px solid #3f3f46', borderRadius: '16px', padding: '24px', display: 'flex', flexDirection: 'column', gap: '20px' },
  sectionHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' },
  sectionTitle: { margin: 0, fontSize: '1.2rem', fontWeight: '700', color: '#f4f4f5' },

  searchBox: { display: 'flex', alignItems: 'center', gap: '8px', backgroundColor: '#27272a', border: '1px solid #3f3f46', padding: '8px 14px', borderRadius: '10px', width: '280px' },
  searchInput: { background: 'none', border: 'none', color: '#ffffff', outline: 'none', fontSize: '0.85rem', width: '100%' },

  emptyCard: { backgroundColor: '#27272a', padding: '40px', borderRadius: '12px', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center' },

  tableWrapper: { overflowX: 'auto' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.85rem' },
  tableHeaderRow: { backgroundColor: '#27272a', borderBottom: '1px solid #3f3f46' },
  th: { padding: '12px 14px', color: '#a1a1aa', fontWeight: '700', textTransform: 'uppercase', fontSize: '0.75rem', letterSpacing: '0.5px' },
  tableRow: { borderBottom: '1px solid #27272a', transition: 'background-color 0.2s' },
  td: { padding: '12px 14px', verticalAlign: 'middle' },

  serialBadge: { backgroundColor: '#27272a', color: '#ea580c', border: '1px solid #ea580c', padding: '4px 8px', borderRadius: '6px', fontWeight: '800', fontSize: '0.75rem' },
  userTableAvatar: { width: '38px', height: '38px', borderRadius: '50%', objectFit: 'cover', border: '2px solid #ea580c' },
  userTableAvatarFallback: { width: '38px', height: '38px', borderRadius: '50%', backgroundColor: '#27272a', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid #3f3f46' },
  ticketCountTag: { backgroundColor: '#27272a', color: '#22c55e', padding: '4px 8px', borderRadius: '6px', fontSize: '0.75rem', fontWeight: '700', display: 'inline-flex', alignItems: 'center', gap: '4px' },

  viewHistoryBtn: { backgroundColor: '#ea580c', color: '#ffffff', border: 'none', padding: '6px 12px', borderRadius: '6px', fontWeight: '600', fontSize: '0.75rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' },
  deleteBtn: { backgroundColor: '#ef4444', color: '#ffffff', border: 'none', padding: '6px 10px', borderRadius: '6px', cursor: 'pointer' },

  /* ABOUT SECTION */
  aboutBanner: { textAlign: 'center', padding: '20px', backgroundColor: '#27272a', borderRadius: '12px', border: '1px solid #3f3f46' },
  aboutBadge: { display: 'inline-flex', alignItems: 'center', gap: '6px', color: '#ea580c', fontWeight: '700', fontSize: '0.8rem' },
  aboutGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '16px' },
  infoBox: { backgroundColor: '#27272a', padding: '16px', borderRadius: '12px', border: '1px solid #3f3f46' },
  infoTitle: { margin: '8px 0 4px 0', color: '#f4f4f5', fontSize: '0.95rem' },
  infoDesc: { margin: 0, color: '#a1a1aa', fontSize: '0.8rem', lineHeight: '1.4' },

  /* HISTORY MODAL */
  modalOverlay: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.85)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 },
  historyModal: { backgroundColor: '#18181b', border: '1px solid #3f3f46', borderRadius: '16px', padding: '24px', width: '90%', maxWidth: '620px', maxHeight: '85vh', overflowY: 'auto' },
  modalHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' },
  modalAvatarImg: { width: '50px', height: '50px', borderRadius: '50%', objectFit: 'cover', border: '2px solid #ea580c' },
  modalAvatarFallback: { width: '50px', height: '50px', borderRadius: '50%', backgroundColor: '#27272a', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '2px solid #ea580c' },
  closeBtn: { background: 'none', border: 'none', color: '#a1a1aa', cursor: 'pointer' },

  userProfileSummaryBox: { backgroundColor: '#27272a', padding: '12px 16px', borderRadius: '10px', display: 'flex', flexWrap: 'wrap', gap: '16px', border: '1px solid #3f3f46', fontSize: '0.82rem', color: '#d4d4d8' },
  summaryItem: { display: 'flex', alignItems: 'center', gap: '6px' },

  noHistoryBox: { padding: '20px', backgroundColor: '#27272a', borderRadius: '10px', textAlign: 'center' },
  historyCardsList: { display: 'flex', flexDirection: 'column', gap: '10px', maxHeight: '320px', overflowY: 'auto' },
  historyCardItem: { backgroundColor: '#27272a', border: '1px solid #3f3f46', borderRadius: '10px', padding: '14px', display: 'flex', flexDirection: 'column', gap: '10px' },
  ticketIdBadge: { backgroundColor: '#18181b', color: '#ea580c', padding: '2px 6px', borderRadius: '4px', fontSize: '0.7rem', fontWeight: '700' },
  paymentMethodTag: { fontSize: '0.75rem', color: '#a1a1aa' },
  ticketFooterDetails: { display: 'flex', gap: '12px', borderTop: '1px solid #3f3f46', paddingTop: '8px' },
  detailChip: { fontSize: '0.75rem', color: '#d4d4d8', display: 'flex', alignItems: 'center', gap: '4px' }
};
